<template>
  <NuxtLink :to="{ name: 'contracts-id', params: { id: contractId } }">
    <LabeledValueIcon
      :label="label || 'Contract'"
      :icon="FileSignatureIcon"
      :loading="!!contractId && isLoading"
      :error="error ? 'Failed to load contract' : undefined"
    >
      <div v-if="data" class="flex flex-row gap-2 flex-wrap items-center">
        <span>from {{ formatShortDate(data.created_at) }}</span>
        <Badge :variant="getContractStatus(data.status).variant" size="sm">
          {{ getContractStatus(data.status).name }}
        </Badge>
      </div>
    </LabeledValueIcon>
  </NuxtLink>
</template>

<script setup lang="ts">
import { FileSignatureIcon } from 'lucide-vue-next';
import LabeledValueIcon from '~/components/common/LabeledValueIcon.vue';
import { getContractShortInfo } from '~/client';
import { getContractStatus } from '~/constants/contracts/contractStatusConfig';
import { formatDateTzToFormat } from '~/utils/formatDateToFormat';

const props = defineProps<{
  label?: string;
  contractId: string;
}>();

const { timezone } = useUserRole();

const { data, isLoading, error } = useQuery({
  key: () => ['contract.short-info', props.contractId ?? ''],
  query: () => getContractShortInfo({ composable: '$fetch', path: { contract_id: props.contractId } }),
});

function formatShortDate(date: string): string {
  return formatDateTzToFormat(new Date(date), 'MM/dd/yyyy', timezone.value);
}
</script>
